    for m in re.finditer(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', t):
        e=m.group()
        if e.lower() in known: ev['exact' if e==e.lower() else 'case_variant']+=1
        else: ev['unknown']+=1
print('evidence emails', ev)
