import csv, re, collections
m={r['file_id']:r for r in csv.DictReader(open('dataset/evidence_files.csv'))}
ev=collections.Counter(); svc_ev=collections.defaultdict(set)
for fid,r in m.items():
    if not r['file_path'].endswith('.log'): continue
    for line in open('dataset/'+r['file_path']):
